	/**
	 * The premise of the rewrite, independent of the optimizer: evaluating the hand-built zero-length path gives the
	 * same bag as the parser's filter over the arbitrary-length path, for stored data with and without cycles and
	 * literal objects, at every tree position, and for caller rows that bind {@code ?s} to a node, to a term that is
	 * not a node, or to nothing.
	 */
	@Test
	void zeroLengthPathReturnsTheBagOfTheFilteredStarPath() {
		List<String> mismatches = new ArrayList<>();
		Set<String> bodiesTheOptimizerLeftAsParsed = new LinkedHashSet<>();
		int comparedWithRows = 0;
		for (Map.Entry<String, List<Statement>> dataset : DATASETS.entrySet()) {
			MemoryStore store = new MemoryStore();
			store.init();
			try (SailConnection connection = store.getConnection()) {
				connection.begin();
				for (Statement statement : dataset.getValue()) {
					connection.addStatement(statement.getSubject(), statement.getPredicate(), statement.getObject());
				}
				connection.commit();
				connection.begin();
				EvaluationStrategy strategy = new DefaultEvaluationStrategy(
						new SailTripleSource(connection, false, store.getValueFactory()), null, null);
				for (String body : BODIES) {
					for (BindingSet input : inputs()) {
						TupleExpr parsed = parse(body);
						TupleExpr manual = parsed.clone();
						assertThat(replaceAliasFiltersWithZeroLengthPaths(manual)).as(body).isPositive();
						TupleExpr optimized = parsed.clone();
						new ReflexiveStarPathOptimizer().optimize(optimized, null, EmptyBindingSet.getInstance());
						// A body the optimizer declines would compare the parsed tree with itself below.
						if (replaceAliasFiltersWithZeroLengthPaths(optimized.clone()) != 0) {
							bodiesTheOptimizerLeftAsParsed.add(body);
						}

						Map<Map<String, Value>, Integer> expected = bag(strategy, parsed, input);
						Map<Map<String, Value>, Integer> manualRows = bag(strategy, manual, input);
						Map<Map<String, Value>, Integer> optimizedRows = bag(strategy, optimized, input);
						if (!expected.isEmpty()) {
							comparedWithRows++;
						}
						if (!expected.equals(manualRows)) {
							mismatches.add(dataset.getKey() + " | " + body + " | input " + input
									+ "\n  filtered star path: " + expected + "\n  zero-length path:   " + manualRows);
						}
						if (!expected.equals(optimizedRows)) {
							mismatches.add(dataset.getKey() + " | " + body + " | input " + input
									+ "\n  filtered star path: " + expected + "\n  optimizer output:   "
									+ optimizedRows);
						}
					}
				}
				connection.commit();
			} finally {
				store.shutDown();
			}
		}
		assertThat(mismatches).isEmpty();
		// Every body is the parser's own tree for a default-graph star over one predicate, so the optimizer rewrites
		// every reflexive star of every body: none is left for the hand-built replacement to find.
		assertThat(bodiesTheOptimizerLeftAsParsed).as("bodies in which the optimizer left a filtered star path")
				.isEmpty();
		// Equal bags only count when the filtered star path returned rows. These nine bodies do, in the "cycles"
		// and in the "literals" data, for each of the two inputs that bind nothing: the three bare stars
		// enumerate the nodes, :a is typed and a node for the two joins with the type pattern and the two unions,
		// "?x :q ?s" has objects that are nodes, and the subselect is the bare star again. 9 * 2 * 2 = 36.
		assertThat(comparedWithRows).as("comparisons in which the filtered star path returned rows")
				.isGreaterThanOrEqualTo(36);
	}

	@Test
	void occupiedNullEndpointsStayUnboundAfterReflexiveRewrite() {
		var store = new MemoryStore();
		store.init();
		try (var connection = store.getConnection()) {
			var blank = VF.createBNode("path-node");
			connection.begin();
			connection.addStatement(blank, P, A);
			connection.commit();
			connection.begin();
			var strategy = new DefaultEvaluationStrategy(
					new SailTripleSource(connection, false, store.getValueFactory()), null);
			for (String body : List.of("?s :p* ?s", "?s ^:p* ?s")) {
				TupleExpr parsed = parse(body);
				var path = (ArbitraryLengthPath) filteredStarPath(parsed).getArg();
				TupleExpr optimized = parsed.clone();
				new ReflexiveStarPathOptimizer().optimize(optimized, null, EmptyBindingSet.getInstance());
				assertThat(replaceAliasFiltersWithZeroLengthPaths(optimized.clone())).isZero();
				TupleExpr plainZeroLength = parsed.clone();
				assertThat(replaceAliasFiltersWithZeroLengthPaths(plainZeroLength)).isOne();
				assertThat(bag(strategy, optimized, EmptyBindingSet.getInstance()).keySet())
						.containsExactlyInAnyOrder(Map.of("s", blank), Map.of("s", A));
				for (String name : List.of(path.getSubjectVar().getName(), path.getObjectVar().getName())) {
					var input = new QueryBindingSet();
					input.setBinding(name, null);
					assertThat(bag(strategy, parsed, input)).as("original %s with occupied %s", body, name).isEmpty();
					assertThat(bag(strategy, optimized, input)).as("rewritten %s with occupied %s", body, name)
							.isEmpty();
					assertThat(bag(strategy, plainZeroLength, input).keySet())
							.containsExactlyInAnyOrder(Map.of("s", blank), Map.of("s", A));
				}
			}
			connection.commit();
		} finally {
			store.shutDown();
		}
	}

